import br.cofra.studio.rtmp.*;import br.cofra.studio.FrameMath;import br.cofra.studio.PcmRing;import java.util.*;import java.io.*;
public class ProtocolTest {
 static int count;static void check(boolean b){count++;if(!b)throw new AssertionError("Verificação "+count);}static void invalid(String u,String k){boolean failed=false;try{new Endpoint(u,k);}catch(IllegalArgumentException e){failed=true;check(!e.getMessage().contains(k));}check(failed);}
 public static void main(String[] args)throws Exception{Endpoint a=new Endpoint("rtmps://example.org/live/","fake-key?auth=1");check(a.tls&&a.port==443&&a.app.equals("live")&&a.stream.equals("fake-key?auth=1"));check(!a.toString().contains("fake-key"));Endpoint b=new Endpoint("rtmp://127.0.0.1:19355/app","s");check(!b.tls&&b.port==19355&&b.tcUrl.equals("rtmp://127.0.0.1:19355/app"));invalid("https://example.org/live","test-not-secret");invalid("rtmp://user:pass@example.org/live","test-not-secret");invalid("rtmp://example.org/live","bad key");invalid("rtmp://example.org:99999/live","test-not-secret");invalid("rtmp://example.org/live?token=x","test-not-secret");
  Map<String,Object> m=Amf0.object("app","live","nome","Coração de João","float",12.5,"flag",true,"nil",null);List<Object> decoded=Amf0.decode(Amf0.encode("connect",1d,m));check(decoded.get(0).equals("connect"));check(((Map<?,?>)decoded.get(2)).get("nome").equals("Coração de João"));check(((Map<?,?>)decoded.get(2)).get("float").equals(12.5));check(Boolean.TRUE.equals(((Map<?,?>)decoded.get(2)).get("flag")));
  byte[] sps={0,0,0,1,0x67,0x42,0,0x1f,1},pps={0,0,1,0x68,1,2};byte[] config=FlvCodec.avcConfig(sps,pps);check(config[0]==0x17&&config[5]==1&&config[10]==(byte)0xe1);byte[] frame=FlvCodec.video(new byte[]{0,0,0,1,0x65,2,3,0,0,1,0x61,4},true);check(frame.length==18&&frame[0]==0x17&&frame[8]==3&&frame[9]==0x65);check(FlvCodec.nals(Arrays.copyOfRange(frame,5,frame.length)).size()==2);check(Arrays.equals(FlvCodec.audio(new byte[]{0x12,8},true),new byte[]{(byte)0xaf,0,0x12,8}));boolean bad=false;try{FlvCodec.nals(new byte[]{0,0,0,10,1});}catch(IOException e){bad=true;}check(bad);check(Amf0.decode(Amf0.encode("ok",null)).size()==2);float[] fit=FrameMath.fit(1440,2560,720,1280,0,0,0);check(fit[0]==1&&fit[1]==1);fit=FrameMath.fit(1920,1080,720,1280,0,0,0);check(fit[0]==1&&fit[1]<1);check(FrameMath.bound(Float.NaN,.3f)==0);check(FrameMath.rgbaToArgb(0xff332211)==0xff112233);
  PcmRing ring=new PcmRing(16);byte[] pcm=new byte[32];for(int i=0;i<32;i++)pcm[i]=(byte)i;ring.put(pcm,32);byte[] out=new byte[16];check(ring.take(out,16)==16&&out[0]==16&&out[15]==31);check(ring.take(out,16)==0);byte[] silence=new byte[16];check(PcmRing.rms(silence,16)==0);byte[] loud=new byte[16];for(int i=0;i<16;i+=2){loud[i]=(byte)0xff;loud[i+1]=0x7f;}PcmRing.mix(loud,loud,16,.35);check(PcmRing.rms(loud,16)<=1);System.out.println("{\"ok\":true,\"checks\":"+count+"}");}
}
